B.push(
{id:"M6-01",m:6,q:"¿Qué es un Fondo Común de Inversión (FCI)?",o:["Una sociedad anónima que invierte por cuenta de sus accionistas","Un patrimonio separado administrado por una sociedad gerente","Una entidad financiera que capta depósitos a plazo del público","Un fideicomiso con oferta pública autorizada por la CNV"],a:1,e:"El FCI no es una sociedad ni una entidad financiera: es un patrimonio separado, y quien lo administra es la sociedad gerente.",r:"M6 · P1"},
{id:"M6-61",m:6,q:"¿Cuál es una característica esencial de los FCI?",o:["Garantizan un rendimiento mínimo al inversor","La cartera la administra cada cuotapartista","Tienen personería jurídica propia, distinta de la gerente","Permiten diversificación de inversiones"],a:3,e:"Al juntar los aportes de muchos inversores, el FCI arma una cartera diversificada que cada uno por separado no podría armar.",r:"M6 · P2"},
{id:"M6-62",m:6,q:"¿Qué ventaja ofrecen los FCI al inversor minorista?",o:["Un rendimiento asegurado por la sociedad gerente","Derecho a voto en las empresas que integran la cartera","Acceso a carteras diversificadas con bajo monto mínimo","La exención de todo costo de administración"],a:2,e:"Con poco dinero el minorista entra a una cartera diversificada y administrada profesionalmente.",r:"M6 · P3"},
{id:"M6-63",m:6,q:"¿Cuál es una desventaja de los FCI?",o:["Los costos de administración","La falta de diversificación de la cartera","La imposibilidad de rescatar en los fondos abiertos","La ausencia de control por parte de la CNV"],a:0,e:"La administración profesional se paga: honorarios y gastos que reducen el rendimiento del cuotapartista.",r:"M6 · P4"},
{id:"M6-03",m:6,q:"¿Qué documento describe las características del FCI?",o:["El contrato de suscripción de cuotapartes","La memoria anual de la sociedad gerente","El reglamento de gestión","El estatuto de la sociedad depositaria"],a:2,e:"El reglamento de gestión es el documento que define las características del fondo: objetivo, política de inversión y comisiones.",r:"M6 · P5"},
{id:"M6-02",m:6,q:"¿Qué norma regula los FCI en Argentina?",o:["Ley 19.550","Ley 24.083","Ley 23.576","Ley 26.831"],a:1,e:"La Ley 24.083 es la ley de Fondos Comunes de Inversión, la primera norma de la bibliografía del módulo.",r:"M6 · P6"},
{id:"M6-64",m:6,q:"¿Cuál es una categoría típica de FCI?",o:["Fondos de garantía de depósitos","Fondos fiduciarios públicos","Fondos de pensión estatales","Fondos de renta fija"],a:3,e:"Renta fija es una de las categorías típicas de FCI, junto con renta variable, mercado de dinero, etc.",r:"M6 · P7"},
{id:"M6-06",m:6,q:"¿Qué significa la suscripción en un FCI?",o:["Compra de cuotapartes por el inversor","La distribución de utilidades a los cuotapartistas","El aporte de capital de la sociedad gerente al fondo","La emisión de acciones del fondo en el mercado"],a:0,e:"Suscribir es entrar al fondo: el inversor compra cuotapartes.",r:"M6 · P8"},
{id:"M6-107",m:6,q:"¿Qué implica el rescate en un FCI?",o:["La liquidación total del fondo por decisión de la gerente","El cobro de la comisión de administración por la gerente","La transferencia de cuotapartes a la sociedad depositaria","Venta de cuotapartes por el inversor"],a:3,e:"Rescatar es salir del fondo: el inversor vende sus cuotapartes y recibe su valor.",r:"M6 · P9"},
{id:"M6-108",m:6,q:"¿Qué documento debe contener la política de inversión del FCI?",o:["Reglamento de gestión","El estatuto de la sociedad gerente","La memoria anual de la sociedad depositaria","El contrato de suscripción de cuotapartes"],a:0,e:"La política de inversión es parte del reglamento de gestión, el documento que rige al fondo.",r:"M6 · P10"},
{id:"M6-65",m:6,q:"¿Qué organismo fiscaliza los FCI?",o:["El Banco Central de la República Argentina","La Unidad de Información Financiera","La Comisión Nacional de Valores","La Inspección General de Justicia"],a:2,e:"El FCI es un producto de inversión colectiva con oferta pública, y su fiscalización está a cargo de la CNV.",r:"M6 · P11"},
{id:"M6-66",m:6,q:"¿Qué norma regula la publicidad y prospectos de FCI?",o:["Normas CNV Título III","Normas CNV Título VII","Normas CNV Título V","Normas CNV Título IX"],a:2,e:"El Título V de las Normas CNV es el de los productos de inversión colectiva: ahí están las reglas de publicidad y prospectos de los FCI.",r:"M6 · P12"},
{id:"M6-109",m:6,q:"¿Qué establece la Ley 24.083 sobre el patrimonio del FCI?",o:["Que integra el patrimonio de la sociedad gerente","Que es un patrimonio separado del de la sociedad gerente","Que es propiedad de la sociedad depositaria","Que responde por las deudas de la sociedad gerente"],a:1,e:"La Ley 24.083 separa el patrimonio del fondo del de la sociedad gerente: los bienes del FCI no se mezclan con los de quien lo administra.",r:"M6 · P13"},
{id:"M6-110",m:6,q:"¿Qué norma regula la custodia de activos del FCI?",o:["Normas CNV Título V","Normas CNV Título IX","Normas CNV Título III","Normas CNV Título XII"],a:0,e:"La custodia de los activos del FCI está regulada en el Título V de las Normas CNV, el de los productos de inversión colectiva.",r:"M6 · P14"},
{id:"M6-111",m:6,q:"¿Qué documento debe aprobar la Comisión Nacional de Valores para autorizar un FCI?",o:["El plan de negocios de la sociedad gerente","El acta constitutiva del fondo","El balance inicial de la sociedad depositaria","Reglamento de gestión"],a:3,e:"Para autorizar un FCI la CNV aprueba su reglamento de gestión, que fija las reglas del fondo.",r:"M6 · P15"},
{id:"M6-67",m:6,q:"¿Qué obligación tienen los FCI respecto a la información periódica?",o:["Publicar balances trimestrales","Publicar un balance sólo al liquidarse el fondo","Informar la cartera únicamente a pedido del cuotapartista","Ninguna: sólo informan a la CNV si ésta lo requiere"],a:0,e:"Según la guía, la obligación de información periódica es publicar balances trimestrales. Ojo: para esta pregunta la guía da \"balances trimestrales\"; en la P44 (estados contables ante la CNV) da \"anualmente\".",r:"M6 · P16"},
{id:"M6-112",m:6,q:"¿Qué norma regula las comisiones de administración de FCI?",o:["Normas CNV Título VII","Normas CNV Título XI","Normas CNV Título V","Normas CNV Título III"],a:2,e:"Las comisiones de administración de los FCI están en el Título V de las Normas CNV, junto con el resto del régimen de los fondos.",r:"M6 · P17"},
{id:"M6-113",m:6,q:"¿Qué ley regula la responsabilidad de la sociedad gerente?",o:["Ley 23.576","Ley 19.550","Ley 24.083","Ley 27.440"],a:2,e:"La responsabilidad de la sociedad gerente está en la Ley 24.083, la ley de Fondos Comunes de Inversión.",r:"M6 · P18"},
{id:"M6-36",m:6,q:"¿Qué es un fideicomiso financiero?",o:["Una sociedad anónima con objeto especial de inversión","Un préstamo sindicado con garantía real sobre los bienes","Un contrato por el cual se transmiten bienes a un fiduciario para un fin determinado","Un mandato por el cual se entregan fondos a un banco para su depósito"],a:2,e:"El fideicomiso nace de un contrato: el fiduciante transmite bienes al fiduciario, que los tiene para un fin determinado.",r:"M6 · P19"},
{id:"M6-68",m:6,q:"¿Qué norma regula los fideicomisos financieros en Argentina?",o:["Ley 19.550","Ley 23.576","Ley 26.831","Ley 24.441"],a:3,e:"La Ley 24.441 (en su parte no derogada) es la ley de fideicomisos que cita la guía.",r:"M6 · P20"},
{id:"M6-114",m:6,q:"¿Cuál es una característica del fideicomiso financiero?",o:["Tiene patrimonio separado del fiduciario","Sus bienes integran el patrimonio del fiduciario","Garantiza un rendimiento mínimo a los beneficiarios","Sus bienes responden por las deudas del fiduciario"],a:0,e:"Los bienes fideicomitidos forman un patrimonio separado: no se mezclan con los del fiduciario ni responden por sus deudas.",r:"M6 · P21"},
{id:"M6-69",m:6,q:"¿Qué documento regula el funcionamiento del fideicomiso?",o:["El acta de directorio del fiduciante","Contrato de fideicomiso","El estatuto del fiduciario","El informe de control y revisión"],a:1,e:"El fideicomiso nace de un contrato, y es ese contrato el que regula su funcionamiento.",r:"M6 · P22"},
{id:"M6-115",m:6,q:"¿Qué organismo fiscaliza los fideicomisos financieros?",o:["El Ministerio de Economía de la Nación","La Inspección General de Justicia","El Banco Central de la República Argentina","Comisión Nacional de Valores"],a:3,e:"Los fideicomisos financieros con oferta pública están bajo la fiscalización de la CNV, igual que los FCI.",r:"M6 · P23"},
{id:"M6-70",m:6,q:"¿Qué norma establece la obligación de inscripción de fideicomisos financieros?",o:["Normas CNV Título V","Normas CNV Título III","Normas CNV Título VII","Normas CNV Título IX"],a:0,e:"Los fideicomisos financieros, como producto de inversión colectiva, están en el Título V de las Normas CNV.",r:"M6 · P24"},
{id:"M6-71",m:6,q:"¿Cuál es una diferencia clave entre FCI y fideicomisos financieros?",o:["El FCI tiene fiduciario; el fideicomiso no","Sólo el FCI tiene un patrimonio separado","El FCI no tiene fiduciario, el fideicomiso sí","Sólo el fideicomiso está bajo control de la CNV"],a:2,e:"En el FCI hay gerente y depositaria, pero no fiduciario. El fideicomiso, en cambio, se estructura alrededor de un fiduciario.",r:"M6 · P25"},
{id:"M6-72",m:6,q:"¿Qué instrumento suele utilizarse para titulización de activos?",o:["El FCI Abierto de Mercado de Dinero","La caución bursátil","El cheque de pago diferido","Fideicomiso financiero"],a:3,e:"En la titulización se transmiten activos (por ejemplo, créditos) a un fideicomiso financiero, que emite valores fiduciarios respaldados por ellos.",r:"M6 · P26"},
{id:"M6-73",m:6,q:"¿Qué riesgo comparten FCI y fideicomisos?",o:["El riesgo de dilución accionaria","El riesgo de gobierno corporativo de la gerente","El riesgo de rescate masivo","Riesgo de mercado"],a:3,e:"En los dos casos el valor de lo invertido depende de los precios de mercado de los activos: es el riesgo que comparten.",r:"M6 · P27"},
{id:"M6-74",m:6,q:"¿Qué ventaja tienen los FCI frente a fideicomisos?",o:["Mayor transparencia normativa","Un rendimiento asegurado por la gerente","La ausencia de costos de administración","El cobro prioritario sobre los tenedores de VDF"],a:0,e:"La guía señala como ventaja del FCI su mayor transparencia normativa frente al fideicomiso.",r:"M6 · P28"},
{id:"M6-75",m:6,q:"¿Qué documento es obligatorio tanto en un FCI como en un Fideicomiso?",o:["El informe de control y revisión","El estatuto de la sociedad gerente","Prospecto","El dictamen de calificación de riesgo"],a:2,e:"La guía marca al prospecto como el documento obligatorio en los dos vehículos.",r:"M6 · P29"},
{id:"M6-76",m:6,q:"¿Qué ley regula aspectos del fideicomiso en el Código Civil y Comercial?",o:["Ley 19.550","Ley 26.994","Ley 23.576","Ley 27.440"],a:1,e:"La Ley 26.994 aprobó el Código Civil y Comercial, que incorporó la regulación del fideicomiso.",r:"M6 · P30"},
{id:"M6-15",m:6,q:"Es correcto que los Fondos Comunes de Inversión tienen permitido efectuar operaciones con instrumentos financieros derivados:",o:["Con fines de cobertura o como inversión para administrar más eficazmente la cartera, mientras la exposición total a riesgo de mercado no supere el patrimonio neto del fondo","Nunca, porque la normativa se los prohíbe","Sólo con fines de cobertura y hasta el 20% del patrimonio","Sólo los fondos destinados a inversores calificados"],a:0,e:"Cobertura o gestión eficiente, con el tope de exposición total al riesgo de mercado igual al patrimonio neto del fondo.",r:"M6 · P31"},
{id:"M6-08",m:6,q:"Respecto de los Fondos Comunes de Inversión Abiertos, ¿cuál de las siguientes afirmaciones es correcta?",o:["Nunca pueden abonar rescates con valores de la cartera","Pueden abonar los rescates con valores de cartera en casos excepcionales con previa autorización de la CNV","Pueden abonar rescates con valores de cartera cuando lo decida la gerente","Sólo abonan rescates al cierre del ejercicio"],a:1,e:"Se admite en casos excepcionales y con autorización previa de la CNV, no por decisión de la gerente.",r:"M6 · P32"},
{id:"M6-77",m:6,q:"¿Cuál de las siguientes afirmaciones respecto de la cartera de un Fondo Común Abierto de Renta Variable destinado al público en general es correcta?",o:["No puede invertir en CEDEAR de ningún tipo, por tratarse de valores con subyacente extranjero","Puede invertir en CEDEAR sólo hasta el 25% del patrimonio neto administrado","Puede invertir hasta el 100% del patrimonio neto en ON emitidas por una misma emisora","Puede invertir hasta 100% del patrimonio neto administrado en CEDEAR cuyo activo subyacente esté constituido por acciones de compañías chilenas"],a:3,e:"La guía admite hasta el 100% del patrimonio neto en CEDEAR con subyacente en acciones de compañías chilenas. En ON de una misma emisora, en cambio, el tope es 20%.",r:"M6 · P33"},
{id:"M6-31",m:6,q:"¿Cuál de las siguientes afirmaciones respecto de los Fondos Comunes Cerrados es correcta?",o:["Admiten rescates diarios, igual que los fondos abiertos","Sólo se pueden adquirir cuotapartes en la colocación primaria","Se pueden adquirir cuotapartes en la colocación primaria y/o en la negociación secundaria","Sólo pueden ser suscriptos por la sociedad gerente"],a:2,e:"El cerrado tiene una cantidad fija de cuotapartes: se entra en la colocación primaria o comprando en el mercado secundario.",r:"M6 · P34"},
{id:"M6-11",m:6,q:"¿Cuál de las siguientes afirmaciones respecto del régimen informativo de los Fondos Comunes de Inversión Abiertos es correcta?",o:["Deben informar la cantidad de cuotapartes, el valor de cuotaparte y patrimonio neto con periodicidad diaria","Deben informar sólo el valor de la cuotaparte, con periodicidad semanal","Deben publicar la composición completa de la cartera cada hora","No tienen un régimen informativo con periodicidad diaria"],a:0,e:"Cuotapartes, valor de cuotaparte y patrimonio neto se informan todos los días.",r:"M6 · P35"},
{id:"M6-32",m:6,q:"¿En cuál de las siguientes categorías debe estar inscripta una sociedad para intervenir en la colocación de un Fondo Común de Inversión Cerrado?",o:["Agente Productor","Agente Asesor Global de Inversión","Agente de Liquidación y Compensación o Agente de Negociación","Sociedad Depositaria"],a:2,e:"ALyC o AN: la colocación de un fondo cerrado es colocación primaria de valores negociables.",r:"M6 · P36"},
{id:"M6-16",m:6,q:"¿Cuál de estas premisas es correcta respecto de la conformación de la cartera de un FCI Abierto destinado al público en general?",o:["Como máximo puede invertir hasta 10% en Obligaciones Negociables emitidas por la misma emisora","Como máximo puede invertir hasta 35% en Obligaciones Negociables emitidas por la misma emisora","Como máximo puede invertir hasta 20% en Obligaciones Negociables emitidas por la misma emisora","Como máximo puede invertir hasta 50% en Obligaciones Negociables emitidas por la misma emisora"],a:2,e:"El tope por emisora en ON es 20%. No confundir con el 30% por misma especie de títulos públicos (P64).",r:"M6 · P37"},
{id:"M6-17",m:6,q:"En un Fondo Común de Inversión Abierto, ¿cuál es el porcentaje máximo de disponibilidades permitido?",o:["10%","25%","50%","No existe un porcentaje máximo"],a:3,e:"Las disponibilidades no tienen tope máximo.",r:"M6 · P38"},
{id:"M6-78",m:6,q:"De acuerdo con la normativa, ninguna de estas carteras cumple con las limitaciones estipuladas para un FCI Abierto especializado en Renta Fija:",o:["40% ON, 30% Títulos Públicos, 25% Acciones y 5% cuotapartes de FCI; y 60% Títulos Públicos, 30% ON y 10% Disponibilidades","50% Títulos Públicos, 40% ON y 10% Disponibilidades; y 25% Letras del Tesoro, 20% Cauciones, 20% CP de FF, 15% Acciones, 10% Bonos Corporativos y 10% Disponibilidades","40% ON, 30% Títulos Públicos, 25% Acciones y 5% cuotapartes de FCI; y 25% Letras del Tesoro, 20% Cauciones, 20% CP de FF, 15% Acciones, 10% Bonos Corporativos y 10% Disponibilidades","70% Títulos Públicos, 20% ON y 10% Disponibilidades; y 45% Letras del Tesoro, 45% ON y 10% Cauciones"],a:2,e:"La guía marca estas dos carteras como las que NO cumplen: la de 40% ON, 30% TP, 25% acciones y 5% FCI, y la de 25% Letras, 20% cauciones, 20% CP, 15% acciones, 10% bonos y 10% disponibilidades.",r:"M6 · P39"},
{id:"M6-13",m:6,q:"La Sociedad Gerente NO tiene por obligación informar a la CNV la siguiente información respecto de un Fondo Común de Inversión Abierto:",o:["El valor de la cuotaparte","La composición de la cartera","Tasa de Rendimiento esperada","El patrimonio neto del fondo"],a:2,e:"La tasa de rendimiento esperada no es algo que la gerente deba informar: un FCI no promete rendimientos.",r:"M6 · P40"},
{id:"M6-24",m:6,q:"En el caso de un FCI de Mercado de Dinero, el Margen de Liquidez debe constituirse sobre la porción de activos:",o:["Que valúen a precio de mercado","Que valúen a Devengamiento","Denominados en moneda extranjera","Con vencimiento mayor a 90 días"],a:1,e:"El margen de liquidez se constituye sobre los activos valuados a devengamiento.",r:"M6 · P41"},
{id:"M6-25",m:6,q:"Un Fondo Común de Inversión de Mercado de Dinero mantiene en cartera las siguientes inversiones, ¿por cuál de ellas se encuentra excedido?",o:["20% en cauciones bursátiles","30% en plazos fijos precancelables","25% en Acciones emitidas en el país","10% en disponibilidades"],a:2,e:"El money market invierte en activos de muy corta duración y alta liquidez; las acciones están fuera de su universo.",r:"M6 · P42"},
{id:"M6-28",m:6,q:"En los Fondos Comunes de Inversión Abiertos ASG el plazo mínimo de conformación de la cartera es de:",o:["30 días corridos","90 días corridos","180 días corridos","1 año"],a:2,e:"180 días corridos para conformar la cartera del fondo ASG.",r:"M6 · P43"},
{id:"M6-12",m:6,q:"¿Con qué periodicidad se tienen que presentar ante la CNV los estados contables por los fondos comunes de inversión abiertos?",o:["Mensualmente","Bimestralmente","Anualmente","Semestralmente"],a:2,e:"La guía indica que se presentan ante la CNV anualmente. Ojo: para esta pregunta la guía da \"anualmente\"; en la P16 (información periódica) da \"publicar balances trimestrales\".",r:"M6 · P44"},
{id:"M6-14",m:6,q:"¿Cuál es el patrimonio neto mínimo para constituir una sociedad gerente con dos fondos comunes de inversión, según Normas CNV?",o:["100.000 UVA","1.000.000 UVA","250.000 UVA","170.000 UVA"],a:3,e:"170.000 UVA para una gerente con dos fondos.",r:"M6 · P45"},
{id:"M6-22",m:6,q:"En un Fondo Común de Inversión PyME, ¿hay exigencias mínimas de inversión?",o:["No, la política de inversión es libre","Sí: como mínimo el 75% del haber debe invertirse en valores negociables emitidos por PyMEs y/o por otras entidades cuya emisión tenga como finalidad el financiamiento de PyMEs","Sí: como mínimo el 50% del haber debe invertirse en valores negociables emitidos por PyMEs","Sí: el 100% del haber debe invertirse en acciones emitidas por PyMEs"],a:1,e:"75% del haber del fondo, en valores de PyMEs o de entidades cuya emisión financie a PyMEs.",r:"M6 · P46"},
{id:"M6-05",m:6,q:"¿Cuál de estas funciones NO se encuentra a cargo de la Sociedad Depositaria de Fondos Comunes de Inversión?",o:["Confeccionar la contabilidad del Fondo","Percibir el importe de las suscripciones","Pagar los rescates a los cuotapartistas","Llevar el registro de cuotapartes escriturales"],a:0,e:"La contabilidad del fondo no es tarea de la Depositaria, que se ocupa de mover el dinero de suscripciones y rescates.",r:"M6 · P47"},
{id:"M6-04",m:6,q:"¿Cuál de estas funciones NO se encuentra a cargo de la Sociedad Gerente de Fondos Comunes de Inversión?",o:["Administrar el fondo y definir la composición de la cartera","Representar a los cuotapartistas en lo relativo a sus intereses","Ejercer los derechos políticos de los valores de la cartera","Desempeñar la guarda y la custodia de valores y demás instrumentos"],a:3,e:"La guarda y custodia de valores es de la Depositaria; la Gerente administra el fondo.",r:"M6 · P48"},
{id:"M6-29",m:6,q:"¿Cuál de estos cargos no son imputados al resultado del Fondo Común de Inversión?",o:["Los honorarios de la sociedad gerente","Comisión de Suscripción","Los honorarios de la sociedad depositaria","Los gastos de auditoría del fondo"],a:1,e:"La comisión de suscripción la paga el cuotapartista al entrar, no se imputa al resultado del fondo.",r:"M6 · P49"},
{id:"M6-30",m:6,q:"¿Quiénes gozan del derecho a la distribución de utilidades devengadas del Fondo Común de Inversión?",o:["La sociedad gerente","La sociedad depositaria","Los cuotapartistas","Los acreedores del fondo"],a:2,e:"Las utilidades son de los cuotapartistas, que son los titulares del fondo.",r:"M6 · P50"},
{id:"M6-07",m:6,q:"En un Fondo Común de Inversión Abierto es posible solicitar rescates:",o:["Sólo totales","Sólo al cierre de cada ejercicio","Sólo parciales, hasta la mitad de la tenencia","Totales o parciales"],a:3,e:"El cuotapartista puede rescatar toda su tenencia o una parte: es la característica central del fondo abierto.",r:"M6 · P51"},
{id:"M6-116",m:6,q:"En un Fondo Común de Inversión Abierto es posible solicitar un rescate:",o:["Hasta una vez por mes","Sólo con preaviso de 72 horas","Hasta el 10% del patrimonio del fondo por día","Sin límite"],a:3,e:"La guía dice que el rescate en un fondo abierto se puede pedir sin límite.",r:"M6 · P52"},
{id:"M6-09",m:6,q:"Indicar el monto que se obtiene del rescate de un FCI si se rescatan 8.512 cuotapartes el 6 de enero de 2020. Comisión de rescate: 2,9%. VCP 5/1: 10,560; VCP 6/1: 10,643; VCP 7/1: 10,892.",o:["$90.593","$87.966","$89.891","$92.712"],a:1,e:"Se usa el VCP del día del rescate: 8.512 × 10,643 = $90.593, menos el 2,9% de comisión → $87.966.",r:"M6 · P53"},
{id:"M6-117",m:6,q:"\"Las operaciones de rescate de Fondos Comunes de Inversión Abiertos no podrán abonarse en ningún caso con valores integrantes de la cartera\". Esta afirmación es:",o:["Verdadera","Falsa: pueden abonarse con valores de cartera cuando lo decida la gerente","Falsa","Verdadera, salvo en los fondos de renta variable"],a:2,e:"Falsa: en casos excepcionales y con autorización previa de la CNV los rescates pueden pagarse con valores de la cartera (P32).",r:"M6 · P54"},
{id:"M6-118",m:6,q:"Un Fondo Común de Inversión es considerado:",o:["Una persona jurídica de derecho privado","Una sociedad anónima de objeto especial","Una parte del patrimonio de la sociedad gerente","Un patrimonio indiviso"],a:3,e:"El FCI no es persona jurídica ni sociedad: es un patrimonio indiviso, que pertenece en común a los cuotapartistas.",r:"M6 · P55"},
{id:"M6-119",m:6,q:"Un Fondo Común de Inversión:",o:["Es un instrumento de inversión colectiva formado por aportes de un grupo de inversores con los mismos objetivos de inversión","Es un instrumento de inversión individual que administra por separado la cartera de cada inversor según su perfil","Es una sociedad formada por aportes de accionistas que votan en asamblea la política de inversión del fondo","Es un contrato de depósito a plazo entre el inversor y la sociedad depositaria, con rendimiento garantizado"],a:0,e:"Es inversión colectiva: muchos inversores con los mismos objetivos juntan sus aportes en un solo fondo.",r:"M6 · P56"},
{id:"M6-79",m:6,q:"\"Para la contabilización de las operaciones efectuadas por los FCI Abiertos será obligatorio el uso del Plan y el Manual de Cuentas de FCI dispuesto por Normas CNV\". Esta afirmación es:",o:["Verdadera","Falsa: cada gerente define su propio plan de cuentas","Falsa","Verdadera sólo para los fondos de renta variable"],a:0,e:"Verdadera: el Plan y el Manual de Cuentas de FCI de las Normas CNV son de uso obligatorio para todos los fondos abiertos.",r:"M6 · P57"},
{id:"M6-80",m:6,q:"\"Para la valuación del Patrimonio Neto de un FCI Abierto deberán utilizarse los criterios de valuación previstos en las Normas CNV\". Esta afirmación es:",o:["Falsa: los fija libremente el reglamento de gestión","Falsa","Verdadera sólo para los fondos de mercado de dinero","Verdadera"],a:3,e:"Verdadera: el patrimonio neto se valúa con los criterios de las Normas CNV, no con los que elija cada gerente.",r:"M6 · P58"},
{id:"M6-10",m:6,q:"El valor de la cuotaparte deberá estar expresado con al menos:",o:["Dos decimales","Tres decimales","Cuatro decimales","Sin decimales"],a:1,e:"Tres decimales como mínimo.",r:"M6 · P59"},
{id:"M6-120",m:6,q:"¿Cuál de las siguientes afirmaciones es correcta para un Fondo Común de Inversión Cerrado?",o:["Sólo requiere Reglamento de Gestión, sin Prospecto de Emisión","Sólo requiere Prospecto de Emisión, sin Reglamento de Gestión","Deberá contar con Reglamento de Gestión y Prospecto de Emisión","Debe pagar rescates diarios a pedido de los cuotapartistas"],a:2,e:"Al fondo cerrado la guía le exige los dos documentos: Reglamento de Gestión y Prospecto de Emisión.",r:"M6 · P60"},
{id:"M6-34",m:6,q:"Es correcto que, a partir de los 13 años, las personas menores de edad pueden cursar órdenes para suscribir:",o:["Cualquier FCI","FCI Abiertos de Mercado de Dinero","FCI Cerrados de infraestructura","Ningún FCI"],a:1,e:"Según la guía, desde los 13 años pueden suscribir FCI Abiertos de Mercado de Dinero.",r:"M6 · P61"},
{id:"M6-81",m:6,q:"Las pruebas de resistencia de mercado, ¿para qué tipos de Fondos Comunes de Inversión son obligatorias?",o:["Para los FCI Abiertos de Mercado de Dinero","Para los FCI Abiertos de Renta Variable","Para los FCI Cerrados","Para los FCI PyME"],a:0,e:"Las pruebas de resistencia de mercado son obligatorias para los money market, los fondos pensados para la liquidez inmediata.",r:"M6 · P62"},
{id:"M6-18",m:6,q:"¿Cuál es el tope de inversión de un FCI en inversiones en controlantes del Administrador o controlantes o controladas del Custodio?",o:["2% del capital o pasivo obligacionario de la controlante o controlada de que se trate, según el último balance anual o subperiódico conocido","5% del patrimonio del fondo, según el último valor de cuotaparte informado","10% del haber del fondo, según el último balance anual del fondo","Está prohibido invertir en ellos, cualquiera sea el monto"],a:0,e:"2%, calculado sobre el capital o pasivo obligacionario del emisor vinculado, según el último balance anual o subperiódico conocido.",r:"M6 · P63"},
{id:"M6-82",m:6,q:"Para un FCI Abierto de renta fija, ¿cuál es el tope de inversión en una MISMA ESPECIE para títulos públicos?",o:["10% del patrimonio del fondo","40% del patrimonio del fondo","30% del patrimonio del fondo","60% del patrimonio del fondo"],a:2,e:"Una misma especie de deuda pública emitida con iguales condiciones (nacional, provincial o municipal) no puede superar el 30% del patrimonio. El 20% es el tope en ON de una misma emisora.",r:"M6 · P64"},
{id:"M6-19",m:6,q:"Para un FCI Abierto de renta variable, ¿cuál es el tope de inversión en Fondos Comunes de Inversión Cerrados administrados por la misma Sociedad Gerente?",o:["Hasta el 15% del haber del Fondo","Sin límite, si el objeto de inversión es compatible","Hasta el 35% del haber del Fondo","Por ser el FCI Cerrado administrado por la propia Sociedad Gerente no podrá invertir en el mismo"],a:3,e:"Prohibición por conflicto de interés: no puede invertir en un cerrado de su propia gerente.",r:"M6 · P65"},
{id:"M6-83",m:6,q:"Para un FCI Abierto ASG, ¿cuál es el tope de inversión en FCI Cerrados administrados por otra Sociedad Gerente?",o:["Hasta el 15% del haber del Fondo, con objeto de inversión compatible","Hasta el 20% del haber del Fondo, con objeto de inversión compatible","Hasta el 10% del haber del Fondo, con objeto de inversión compatible","Hasta el 35% del haber del Fondo, con objeto de inversión compatible"],a:2,e:"ASG: 10% del haber en cerrados de otra gerente con objeto compatible (igual que Infraestructura; PyME es 5% e Inversores Calificados 25%).",r:"M6 · P66"},
{id:"M6-21",m:6,q:"Para un FCI Abierto PYMES, ¿cuál es el tope de inversión en FCI Cerrados administrados por otra Sociedad Gerente?",o:["Hasta el 5% del haber del Fondo, con objeto de inversión compatible","Hasta el 3% del haber del Fondo, con objeto de inversión compatible","Hasta el 15% del haber del Fondo, con objeto de inversión compatible","Hasta el 20% del haber del Fondo, con objeto de inversión compatible"],a:0,e:"En los fondos PyME el tope es el más bajo de la serie: 5% del haber.",r:"M6 · P67"},
{id:"M6-121",m:6,q:"Para un FCI Abierto para el Financiamiento de la Infraestructura y la Economía Real, ¿cuál es el tope de inversión en FCI Cerrados administrados por otra Sociedad Gerente?",o:["Hasta el 50% del haber del Fondo, con objeto de inversión compatible","Hasta el 7% del haber del Fondo, con objeto de inversión compatible","Hasta el 15% del haber del Fondo, con objeto de inversión compatible","Hasta el 10% del haber del Fondo, con objeto de inversión compatible"],a:3,e:"Infraestructura y Economía Real: 10% del haber, el mismo tope que los ASG.",r:"M6 · P68"},
{id:"M6-20",m:6,q:"Para un FCI Abierto destinado exclusivamente a Inversores Calificados, ¿cuál es el tope de inversión en Fondos Comunes de Inversión Cerrados?",o:["Hasta el 15% del haber del Fondo","Hasta el 35% del haber del Fondo","Hasta el 25% del haber del Fondo","Hasta el 50% del haber del Fondo"],a:2,e:"Para inversores calificados el tope en cerrados de otra gerente es el más alto de la serie: 25% del haber.",r:"M6 · P69"},
{id:"M6-23",m:6,q:"¿Cuál de las siguientes afirmaciones es correcta para un Fondo Común de Inversión Abierto de Renta Variable?",o:["Podrá invertir en cuotapartes de cualquier FCI Abierto, hasta el 20% del haber","Podrá invertir en cuotapartes de FCI Abiertos, exclusivamente en Fondos Comunes de Dinero administrados por otra Sociedad Gerente, por hasta el 5% del haber del Fondo","Podrá invertir sólo en cuotapartes de fondos de la misma gerente","No podrá invertir en cuotapartes de otros fondos"],a:1,e:"Sólo money market de otra gerente y hasta el 5% del haber.",r:"M6 · P70"},
{id:"M6-26",m:6,q:"En un Fondo Común de Dinero Clásico se encuentra admitida la adquisición de títulos representativos de deuda, cuyo vencimiento final no exceda un año a partir de la fecha de adquisición:",o:["Por hasta el 20% del Patrimonio Neto del Fondo","Por hasta el 50% del Patrimonio Neto del Fondo","Por hasta el 75% del Patrimonio Neto del Fondo","No está admitida en ningún porcentaje"],a:0,e:"Clásico: hasta 20%. Por eso es el de menor volatilidad y sensibilidad a la tasa.",r:"M6 · P71"},
{id:"M6-84",m:6,q:"En un Fondo Común de Dinero Dinámico se encuentra admitida la adquisición de títulos representativos de deuda, cuyo vencimiento final no exceda un año a partir de la fecha de adquisición:",o:["Por hasta el 40% del Patrimonio Neto del Fondo","Por hasta el 50% del Patrimonio Neto del Fondo","Por hasta el 75% del Patrimonio Neto del Fondo","Por hasta el 100% del Patrimonio Neto del Fondo"],a:3,e:"Dinámico: hasta 100%. Por eso tiene mayor volatilidad y sensibilidad a la tasa que el clásico.",r:"M6 · P72"},
{id:"M6-27",m:6,q:"\"Los Fondos Comunes de Dinero Clásicos presentan mayor volatilidad y sensibilidad al cambio de tasas de interés y exposición al riesgo que los Fondos Comunes de Dinero Dinámicos\". Esta afirmación es:",o:["Falsa","Verdadera","Verdadera sólo en contextos inflacionarios","Depende de la sociedad gerente"],a:0,e:"Es al revés: el clásico es más conservador, con menor volatilidad y exposición al riesgo.",r:"M6 · P73"},
{id:"M6-122",m:6,q:"\"Los Fondos Comunes de Dinero Clásicos presentan menor volatilidad y sensibilidad al cambio de tasas de interés y exposición al riesgo que los Fondos Comunes de Dinero Dinámicos\". Esta afirmación es:",o:["Falsa: los dos tienen la misma volatilidad por ser money market","Falsa","Verdadera sólo en contextos de suba de tasas","Verdadera"],a:3,e:"Verdadera: el clásico sólo admite hasta 20% en deuda de hasta un año, contra 100% del dinámico, y por eso es el más conservador.",r:"M6 · P74"},
{id:"M6-33",m:6,q:"\"Es posible la fusión de dos Fondos Comunes de Inversión Abiertos administrados por distintas Sociedades Gerentes\". Esta afirmación es:",o:["Verdadera, con autorización previa de la CNV","Falsa","Verdadera","Verdadera, si ambos fondos tienen el mismo objeto de inversión"],a:1,e:"Falsa: no pueden fusionarse fondos abiertos de gerentes distintas.",r:"M6 · P75"},
{id:"M6-38",m:6,q:"A los efectos de la constitución de un Fideicomiso Financiero, las Normas CNV prohíben:",o:["Que el fiduciante sea una PyME","Que el beneficiario sea una persona humana","Que existan múltiples fiduciantes en una misma emisión","La constitución de fideicomisos por acto unilateral, entendiéndose por tales aquellos en los que coincidan las personas de Fiduciante y Fiduciario"],a:3,e:"No puede coincidir fiduciante con fiduciario: sería un acto unilateral.",r:"M6 · P76"},
{id:"M6-47",m:6,q:"Cuando el o los Fiduciarios deleguen la ejecución de las funciones de administración, el agente de cobro deberá depositar en una cuenta del fideicomiso, operada exclusivamente por el o los Fiduciarios, los fondos provenientes de las cobranzas:",o:["En un plazo de 24 horas","En un plazo determinado de 3 días hábiles","En un plazo de 5 días hábiles","En un plazo de 10 días corridos"],a:1,e:"3 días hábiles para el depósito de las cobranzas.",r:"M6 · P77"},
{id:"M6-44",m:6,q:"El documento básico a través del cual se realiza la oferta pública de valores fiduciarios es:",o:["El informe de control y revisión","El acta de directorio del fiduciario","El aviso de resultado de la colocación","El Prospecto/Suplemento de Prospecto"],a:3,e:"La oferta pública de valores fiduciarios se hace a través del Prospecto o su Suplemento.",r:"M6 · P78"},
{id:"M6-37",m:6,q:"El Fideicomisario es la persona a quien se le transmite la propiedad fiduciaria al concluir el Fideicomiso. Por lo que podrá ser:",o:["Únicamente un tercero ajeno al contrato","El Fiduciante; el Beneficiario y/o un tercero","Únicamente el Fiduciario","Únicamente el Beneficiario"],a:1,e:"Fiduciante, beneficiario o un tercero. El único que no puede quedarse con los bienes es el fiduciario.",r:"M6 · P79"},
{id:"M6-45",m:6,q:"El proceso de colocación primaria de valores fiduciarios deberá ser llevado a cabo:",o:["A través de sistemas informáticos presentados por los Mercados autorizados por la Comisión","Por venta directa del fiduciario a inversores calificados","Mediante subasta privada organizada por el fiduciante","Por adjudicación proporcional entre los fiduciantes"],a:0,e:"La colocación primaria pasa por los sistemas informáticos de los mercados autorizados por la CNV.",r:"M6 · P80"},
{id:"M6-43",m:6,q:"En el caso de Fideicomisos cuyo activo fideicomitido esté constituido total o parcialmente por dinero u otros activos líquidos coincidirán las figuras de:",o:["Fiduciante y Fiduciario","Fiduciante – Beneficiario","Fiduciario y Beneficiario","Beneficiario y Fideicomisario"],a:1,e:"Quien aporta el dinero es a la vez el beneficiario del resultado de la inversión.",r:"M6 · P81"},
{id:"M6-39",m:6,q:"En el marco de un Fideicomiso Financiero con Oferta Pública se emiten valores fiduciarios, los cuales podrán ser representados de acuerdo a los derechos que otorguen como:",o:["Únicamente valores de deuda fiduciaria","Valores de deuda fiduciaria y/o certificados de participación y/o valores fiduciarios atípicos en los términos del artículo 1820 del CCyCN","Únicamente certificados de participación","Acciones preferidas del fiduciario"],a:1,e:"VDF (deuda), CP (participación) y los atípicos del art. 1820 del CCyCN.",r:"M6 · P82"},
{id:"M6-46",m:6,q:"La administración de un FF fue delegada en el Fiduciante, que incumple con el depósito de las cobranzas en el tiempo y la forma requeridos, lo cual impacta negativamente en el pago de servicios de los valores fiduciarios. Ud. inicia el reclamo correspondiente ante:",o:["El fiduciante","El fiduciario","La CNV","El agente de control y revisión"],a:1,e:"El fiduciario es el responsable frente a los tenedores, aunque haya delegado funciones.",r:"M6 · P83"},
{id:"M6-48",m:6,q:"La custodia de los bienes fideicomitidos corresponde al Fiduciario, sin embargo, éste podrá delegar la ejecución de tales funciones en:",o:["El Fiduciante, en caso de que se trate de entidad financiera","Cualquier fiduciante, sin restricción","El agente de control y revisión","Un depositario del exterior"],a:0,e:"Sólo si el fiduciante es entidad financiera. Una empresa comercial cualquiera no puede ser agente de custodia.",r:"M6 · P84"},
{id:"M6-85",m:6,q:"La portada de la Serie XV de un FF indica: VDF A 500 millones, VDF B 300 millones, CP 100 millones; inversores calificados: SÍ; destinado al financiamiento PyME: SÍ. ¿A quién podría ofrecerle el producto?",o:["A cualquier persona humana del público en general, por tratarse de un FF con oferta pública","A un Municipio del interior de la Pcia. de Buenos Aires; a Juan X, persona humana inscripta en el Registro de Idóneos de la CNV; y a John Y, domiciliado en EE.UU.","Únicamente a PyMEs CNV, por tratarse de un fideicomiso destinado al financiamiento PyME","Sólo a inversores locales, nunca a personas domiciliadas en el exterior del país"],a:1,e:"Al ser una serie para inversores calificados, la guía admite ofrecerla al municipio, a la persona humana inscripta como idónea y al inversor domiciliado en EE.UU.",r:"M6 · P85"},
{id:"M6-86",m:6,q:"La subasta o licitación pública de valores fiduciarios no deberá ser:",o:["Ciega o cerrada para Tramo Competitivo; abierta para Tramo No Competitivo","Abierta para el Tramo Competitivo; ciega para el Tramo No Competitivo","Realizada a través de los sistemas informáticos de los Mercados autorizados","Difundida previamente mediante el Prospecto o Suplemento"],a:0,e:"La guía prohíbe la subasta ciega en el tramo competitivo y la abierta en el no competitivo. Los sistemas de los mercados autorizados son justamente el canal obligatorio de colocación.",r:"M6 · P86"},
{id:"M6-87",m:6,q:"Le consultan sobre la viabilidad de que el Fiduciante, una empresa dedicada exclusivamente a la comercialización de electrodomésticos, sea el Agente de Custodia de los documentos que respaldan los Bienes Fideicomitidos. Usted contesta:",o:["Puede, si lo aprueba la asamblea de tenedores","Puede, porque la custodia siempre puede delegarse en el fiduciante","El Fiduciante en cuestión no puede ser designado como agente de custodia","Puede, si el fiduciario lo autoriza por escrito"],a:2,e:"La custodia sólo puede delegarse en el fiduciante cuando éste es una entidad financiera; una comercializadora de electrodomésticos no lo es.",r:"M6 · P87"},
{id:"M6-40",m:6,q:"Los valores representativos de deuda podrán ser emitidos por:",o:["Únicamente el Fiduciario","El Fiduciario, el Fiduciante o un tercero","Únicamente el Fiduciante","La CNV, en representación del fideicomiso"],a:1,e:"Los valores representativos de deuda pueden ser emitidos por cualquiera de los tres.",r:"M6 · P88"},
{id:"M6-88",m:6,q:"Se presenta un potencial inversor, quien se describe a sí mismo como averso al riesgo, con la intención de adquirir valores fiduciarios. Usted le recomendaría que invierta su dinero en:",o:["Un fideicomiso de capital emprendedor recién estructurado, todavía sin activos originados","Certificados de participación de un fideicomiso inmobiliario con la obra en construcción","Un fideicomiso privado, sin autorización de oferta pública, con créditos de consumo","Un FF serie 132 autorizado por la CNV y cuyo activo subyacente esté constituido por créditos de consumo ya originados"],a:3,e:"Para un perfil conservador: un FF autorizado por la CNV cuyo activo son créditos que ya existen. Ojo: para esta pregunta la guía da el FF serie 132; en la P90, con el mismo enunciado, da los valores de deuda fiduciaria senior.",r:"M6 · P89"},
{id:"M6-41",m:6,q:"Se presenta un potencial inversor, quien se describe a sí mismo como averso al riesgo, con la intención de adquirir valores fiduciarios. Usted le recomendaría que invierta su dinero en:",o:["Certificados de participación, con mayor riesgo pero mayor rentabilidad","Valores de deuda fiduciaria senior, con bajo riesgo pero menor rentabilidad","Valores de deuda fiduciaria subordinados, con mayor tasa y mayor riesgo","Valores fiduciarios atípicos de un fideicomiso de capital emprendedor"],a:1,e:"Los VDF senior cobran primero: menos riesgo a cambio de menos rentabilidad. Ojo: para esta pregunta la guía da los VDF senior; en la P89, con el mismo enunciado, da el FF serie 132 con créditos ya originados.",r:"M6 · P90"},
{id:"M6-42",m:6,q:"Un Fideicomiso Financiero con Oferta Pública es aquel en el cual:",o:["El Fiduciario es una entidad inscripta en el registro de Fiduciarios Financieros de la Comisión y los Beneficiarios son los titulares de los valores fiduciarios","El Fiduciante debe cotizar sus acciones en un mercado autorizado por la Comisión","El Fiduciario es designado por la asamblea de tenedores de los valores fiduciarios","Los bienes fideicomitidos son de propiedad de los beneficiarios desde la emisión"],a:0,e:"Fiduciario inscripto en el registro de la CNV + beneficiarios = tenedores de los valores fiduciarios.",r:"M6 · P91"},
{id:"M6-89",m:6,q:"Un inversor adquirió valores representativos de deuda de un FF y le pide información del devenir del mismo al último cierre de estado contable del Fideicomiso. Ud. le recomienda:",o:["Pedirle los estados contables del fideicomiso directamente al fiduciante","Consultar el sitio web de la CNV y analizar la información mensual contenida en el informe de control y revisión","Esperar a la próxima asamblea anual de tenedores para recibir un informe","Consultar el reglamento de gestión del fideicomiso publicado por el fiduciario"],a:1,e:"El informe mensual de control y revisión se publica en el sitio web de la CNV y es la fuente para seguir la evolución del fideicomiso.",r:"M6 · P92"},
{id:"M6-52",m:6,q:"Un cliente sin Certificado MiPyME vigente, titular de una cartera de cheques de pago diferido que financian PyMEs, pretende constituir como Fiduciante un FF destinado al financiamiento de PyME. ¿Cuál de las siguientes estructuras fiduciarias le propone?",o:["Un FF con al menos el 70% del activo fideicomitido (valor nominal) en CPD de operaciones con PyMEs CNV y el 30% restante en CPD de otros deudores","Un FF con al menos el 50% del activo fideicomitido en CPD de PyMEs CNV y el resto en CPD de otros deudores","Ninguna: no puede constituirlo por carecer del Certificado MiPyME vigente","Un FF con el 100% del activo fideicomitido en CPD de PyMEs, sin admitir otros deudores"],a:0,e:"El fiduciante no PyME igual puede calificar si al menos el 70% del activo, a valor nominal, proviene de operaciones con PyMEs CNV.",r:"M6 · P93"},
{id:"M6-123",m:6,q:"Un potencial inversor quiere invertir en un Fideicomiso cuyo activo fideicomitido esté constituido total o parcialmente por dinero u otros activos líquidos. Ud. le aclara que pasará a participar del Fideicomiso en carácter de:",o:["Fiduciario – Fideicomisario","Beneficiario únicamente","Fiduciante – Beneficiario","Fiduciante – Fiduciario"],a:2,e:"Si aporta dinero u otros activos líquidos, el inversor es fiduciante (aporta) y beneficiario (recibe el resultado) a la vez.",r:"M6 · P94"},
{id:"M6-90",m:6,q:"Un potencial inversor le solicita en detalle los términos y condiciones de la emisión de un fideicomiso financiero recientemente publicado en el boletín del mercado. Usted pone a su disposición:",o:["El Prospecto/Suplemento de Prospecto/Contrato de Fideicomiso","El aviso de resultado de la colocación publicado por el mercado","El acta de directorio del fiduciario que aprobó la emisión","Los estados contables anuales y trimestrales del fiduciario"],a:0,e:"Los términos y condiciones de la emisión están en el prospecto, su suplemento y el contrato de fideicomiso.",r:"M6 · P95"},
{id:"M6-91",m:6,q:"Una persona quiere participar de la oferta pública primaria de un FF inmobiliario autorizado hace 3 años, en cuyos términos está prevista la reapertura del período de colocación. Ud. le manifiesta que:",o:["Puede suscribir en cualquier momento, directamente con el fiduciario y sin esperar","No puede participar: pasados 3 años ya no puede reabrirse el período de colocación","Aguarde a la reapertura del período de colocación dispuesto en el suplemento y allí presente su oferta","Debe pedir una nueva autorización de oferta pública a la CNV para poder suscribir"],a:2,e:"Si la reapertura está prevista, hay que esperar a que se reabra el período de colocación y ofertar ahí.",r:"M6 · P96"},
{id:"M6-53",m:6,q:"Los valores negociables que se emitan en el marco de los Productos de Inversión Colectiva para el Desarrollo de Infraestructura:",o:["Pueden ser adquiridos por cualquier inversor del público en general","Solo podrán ser adquiridos por los inversores calificados definidos en la Sección I del Capítulo VI del Título II de las Normas","Sólo pueden ser adquiridos por el Estado Nacional y las provincias","Sólo pueden ser adquiridos si cuentan con calificación de riesgo AAA"],a:1,e:"Están reservados a los inversores calificados que definen las Normas CNV.",r:"M6 · P97"},
{id:"M6-51",m:6,q:"Serán considerados fideicomisos financieros destinados al financiamiento de PYMES cuando:",o:["El fiduciario sea una PyME CNV inscripta en el registro de la Comisión","Se cumpla al menos uno de los supuestos: fiduciantes PyME CNV; o, con fiduciantes no PyME, al menos el 70% del activo en créditos con PyMEs CNV; o, con pluralidad de fiduciantes, el 70% transferido por fiduciantes PyME; o, como fondo de inversión directa, el 70% aplicado a operaciones con PyMEs","Al menos el 50% del activo fideicomitido provenga de operaciones con PyMEs","Lo autorice la autoridad de aplicación de la Ley PyME a pedido del fiduciante"],a:1,e:"Basta con cumplir uno de los supuestos i, ii, iii o iv. El umbral en los tres últimos es el 70%.",r:"M6 · P98"},
{id:"M6-92",m:6,q:"Se consideran Productos de Inversión Colectiva para el desarrollo de Infraestructura a los FF con autorización de oferta pública de la CNV cuyo objeto se encuentre destinado:",o:["Exclusivamente al financiamiento de obra pública del Estado Nacional, en forma directa","Directa o indirectamente al desarrollo, inversión, financiamiento de una Infraestructura Pública o de Infraestructura Privada","Al financiamiento del consumo de las familias a través de créditos personales","Exclusivamente a la infraestructura privada de PyMEs, sin admitir la infraestructura pública"],a:1,e:"El objeto abarca infraestructura pública o privada, y puede ser en forma directa o indirecta.",r:"M6 · P99"},
{id:"M6-60",m:6,q:"En los Fideicomisos Financieros destinados al Desarrollo Inmobiliario, ¿podrá preverse la reapertura del Período de Colocación de los Valores Fiduciarios ya autorizados?",o:["No, en ningún caso","Sí, mientras se encuentre previsto en el Prospecto y en el Contrato; no se exceda de los 5 años desde iniciado el Período de Colocación original o hasta alcanzar el monto autorizado","Sí, sin límite temporal, mientras lo decida el fiduciario","Sólo con una nueva autorización de oferta pública de la CNV"],a:1,e:"Previsión en el Prospecto y el Contrato, con tope de 5 años desde la colocación original o hasta el monto autorizado.",r:"M6 · P100"},
{id:"M6-93",m:6,q:"¿Cuál de estos es un objeto válido para un FF para el fomento del Desarrollo Productivo y de las Economías Regionales (Capítulo VIII del Título V de las Normas CNV)?",o:["La adquisición de CEDEARs de empresas tecnológicas que cotizan en el exterior","El financiamiento de préstamos personales de consumo otorgados en grandes ciudades","La compra de Letras del Tesoro Nacional para mantener hasta su vencimiento","La explotación de un negocio de producción agropecuario en el litoral llevado a cabo por una empresa con presencia multinacional"],a:3,e:"Es producción real en una economía regional; que la empresa sea multinacional no le quita validez al objeto.",r:"M6 · P101"},
{id:"M6-94",m:6,q:"En un fideicomiso de capital emprendedor con vehículo de tinte tecnológico, cuyo Fiduciario no tiene la experiencia necesaria, ¿qué es lo correcto para integrar el Prospecto como \"Gestor Profesional\"?",o:["Agro Pampa S.A., inscripta en la IGJ en 2010, dedicada a la exportación de granos y oleaginosas","Tecno Road S.A., inscripta en la IGJ el 01-01-2015, dedicada a brindar y gestionar soluciones tecnológicas para empresas nacionales","El propio Fiduciario, aunque no tenga la experiencia necesaria en el objeto tecnológico del vehículo","Inmobiliaria del Sur S.R.L., inscripta en la IGJ en 2012, dedicada a la construcción de viviendas"],a:1,e:"El gestor tiene que aportar la experiencia que le falta al fiduciario en el objeto del vehículo: Tecno Road es la que se dedica a soluciones tecnológicas.",r:"M6 · P102"},
{id:"M6-49",m:6,q:"En caso de que se desee modificar una condición esencial de la emisión establecida en el contrato de fideicomiso financiero, ¿con cuál de estos requisitos debe cumplir para que esa modificación sea válida?",o:["Obtener la mayoría simple de los tenedores presentes en la asamblea","Obtener el consentimiento unánime de los tenedores de valores fiduciarios emitidos y en circulación","Obtener únicamente la aprobación de la CNV","Obtener dos tercios de los tenedores presentes en la asamblea"],a:1,e:"Para tocar una condición esencial hace falta la unanimidad de los tenedores de valores en circulación.",r:"M6 · P103"},
{id:"M6-95",m:6,q:"Si se optase por llevar a cabo una asamblea con modalidad a distancia, ¿cuál requisito es obligatorio para garantizar la validez de estas reuniones?",o:["Que un funcionario de la CNV presencie la reunión y firme el acta correspondiente","Que todas las decisiones se tomen por unanimidad de los tenedores presentes","Que la reunión se grabe en soporte digital y se garantice que todos los participantes puedan identificarse correctamente","Que todos los participantes se encuentren en el país al momento de la reunión"],a:2,e:"La grabación en soporte digital y la correcta identificación de los participantes son las que garantizan la validez de la reunión a distancia.",r:"M6 · P104"},
{id:"M6-50",m:6,q:"Ante una situación en la que el patrimonio del fideicomiso resulta insuficiente para cumplir sus obligaciones, ¿qué mayoría es necesaria para tomar decisiones válidas?",o:["Mayoría simple de los tenedores presentes","Dos tercios de los valores fiduciarios presentes","Al menos tres cuartas partes de los valores fiduciarios emitidos y en circulación","Mayoría absoluta de los valores fiduciarios presentes"],a:2,e:"Con patrimonio insuficiente se exigen al menos tres cuartas partes de los valores fiduciarios emitidos y en circulación.",r:"M6 · P105"},
{id:"M6-58",m:6,q:"Indique cuáles de estas condiciones se deben cumplir para que una serie pueda acceder al régimen de Fideicomisos Financieros con Autorización Automática de Emisiones Frecuentes:",o:["Tiene que haber emitido al menos 7 fideicomisos financieros en total y de ellos, 3 en los últimos 12 meses","Tiene que haber emitido al menos 3 fideicomisos financieros en total, sin importar en qué período","Tiene que contar con calificación de riesgo del programa y de cada una de sus series anteriores","Tiene que acreditar un patrimonio neto mínimo del fiduciante de 500.000 UVA"],a:0,e:"Hacen falta 7 fideicomisos en total, y 3 de ellos emitidos en los últimos 12 meses.",r:"M6 · P106"},
{id:"M6-96",m:6,q:"En el caso de Fideicomisos Financieros con Autorización Automática de Emisiones Frecuentes, indicar cuáles son las idénticas características que tienen que presentar en lo sustancial:",o:["Programa, Fiduciario, Fiduciante y similar composición del Activo subyacente","Monto de emisión, tasa de interés y plazo de amortización de los valores","Agente colocador, mercado de listado y organizador de la emisión","Calificación de riesgo, auditor externo y agente de control y revisión"],a:0,e:"Lo que tiene que repetirse es la estructura: mismo programa, fiduciario y fiduciante, y un activo subyacente de composición similar.",r:"M6 · P107"},
{id:"M6-97",m:6,q:"¿Cuál de las siguientes enunciaciones relativas a las Ofertas Públicas con Autorización Automática por su Mediano Impacto es correcta?",o:["Los valores fiduciarios serán considerados colocados por oferta pública por el solo hecho de estar autorizados, aunque no haya esfuerzos de colocación","Los valores fiduciarios serán considerados colocados por oferta pública siempre que sean efectivamente colocados mediante esfuerzos acreditables por los medios del artículo 2° de la Ley 26.831","Los valores fiduciarios serán considerados colocados por oferta pública sólo si los coloca en forma privada el fiduciante entre inversores calificados","Los valores fiduciarios serán considerados colocados por oferta pública sólo si la CNV aprueba en forma previa cada colocación"],a:1,e:"La autorización es automática, pero la oferta pública no: requiere esfuerzos de colocación acreditables por los medios del art. 2° de la Ley 26.831.",r:"M6 · P108"},
{id:"M6-98",m:6,q:"Conforme las Normas (N.T. 2013 y mod.), el Prospecto de emisión de un fideicomiso financiero con autorización automática por su mediano Impacto:",o:["Deberá ser publicado al cierre del período de colocación, únicamente en el boletín diario del mercado donde se listen","Deberá ser presentado ante la CNV dentro de los 5 días hábiles posteriores a la emisión de los valores fiduciarios","No deberá publicarse: alcanza con publicar el contrato de fideicomiso en la AIF antes de la colocación","Deberá ser publicado al inicio del plazo de difusión a través de la AIF y en los sistemas de información de los mercados autorizados donde se listen y negocien los valores fiduciarios"],a:3,e:"Al arrancar la difusión, en la Autopista de la Información Financiera y en los sistemas de los mercados donde se listan y negocian los valores.",r:"M6 · P109"},
{id:"M6-99",m:6,q:"\"La presentación de EE.CC. trimestrales es opcional en aquellos fideicomisos financieros que se constituyan como fondos de inversión directa\". Esta afirmación resulta:",o:["Correcta","Correcta, si lo autoriza la CNV","Incorrecta","Correcta sólo durante el primer ejercicio"],a:2,e:"Incorrecta: la trimestral opcional es para el resto de los FF; los fondos de inversión directa quedan fuera de esa opción (P115).",r:"M6 · P110"},
{id:"M6-100",m:6,q:"En los Prospectos de los Programas Globales de FF que prevean exclusivamente la constitución de fideicomisos financieros como fondos de inversión directa, los fiduciantes:",o:["Pueden no estar identificados si se encuentra expresamente delimitado el objeto de inversión de los fideicomisos a constituirse bajo el Programa","Deben estar siempre identificados en el prospecto, junto con sus estados contables de los tres últimos ejercicios","Deben ser necesariamente PyMEs CNV, dado que se trata de fondos de inversión directa","Deben coincidir con el fiduciario del programa, que actúa también como fiduciante"],a:0,e:"En los fondos de inversión directa lo que se exige delimitar es el objeto de inversión; con eso, los fiduciantes pueden no estar identificados.",r:"M6 · P111"},
{id:"M6-101",m:6,q:"¿Con qué periodicidad debe ser actualizado el PIPE (Plan de Inversión, Producción y Estratégico) en los fideicomisos financieros constituidos como fondos de inversión directa?",o:["Trimestralmente, con la presentación de los EE.CC. trimestrales","Anualmente, con la presentación de los EE.CC. anuales del fideicomiso financiero","Semestralmente, con un informe especial del agente de control","Sólo una vez, al momento de la autorización de oferta pública"],a:1,e:"El PIPE se actualiza una vez por año, junto con los estados contables anuales del fideicomiso.",r:"M6 · P112"},
{id:"M6-55",m:6,q:"A fin de acreditar el cumplimiento del requisito patrimonial requerido a los Fiduciarios Financieros, ¿cuál es el plazo de presentación de los estados contables trimestrales?",o:["Dentro de los 15 días hábiles de cerrado cada trimestre","Dentro de los 42 días corridos de cerrado cada trimestre","Dentro de los 70 días corridos de cerrado cada trimestre","Dentro de los 30 días hábiles de cerrado cada trimestre"],a:1,e:"Cuarenta y dos días corridos desde el cierre de cada trimestre.",r:"M6 · P113"},
{id:"M6-102",m:6,q:"¿Cuál es la antigüedad requerida para que la información contable del Suplemento de Prospecto en la Sección \"Descripción del Fiduciante\" se encuentre debidamente actualizada para la autorización de oferta pública?",o:["El último ejercicio anual cerrado, más el último balance trimestral","Los dos últimos ejercicios anuales, sin excepciones por antigüedad","Los cinco últimos ejercicios anuales, o desde su constitución si fuere menor","Tres (3) últimos ejercicios anuales o desde su constitución, si su antigüedad fuere menor"],a:3,e:"Tres ejercicios anuales; si el fiduciante es más nuevo, desde su constitución.",r:"M6 · P114"},
{id:"M6-54",m:6,q:"¿Cuál es la periodicidad exigida para la presentación de estados contables de Fideicomisos Financieros, excepto para aquellos que se constituyan como \"Fondos de Inversión Directa\"?",o:["Por subperíodos trimestrales en forma obligatoria","Por períodos anuales y, opcionalmente, por subperíodos trimestrales","Por períodos mensuales","Por períodos semestrales"],a:1,e:"Anual obligatoria y trimestral opcional. En los fondos de inversión directa la trimestral no es opcional (P110).",r:"M6 · P115"},
{id:"M6-57",m:6,q:"En caso de que la función de control y revisión de los activos subyacentes de los fideicomisos y el flujo de fondos que generan sea ejercida por un Contador Público Independiente matriculado, ¿cuál es la antigüedad en la matrícula requerida?",o:["No inferior a tres (3) años","No inferior a cinco (5) años","No inferior a diez (10) años","No se exige antigüedad"],a:1,e:"Cinco años de matrícula como mínimo.",r:"M6 · P116"},
{id:"M6-56",m:6,q:"¿Cuál es el plazo de presentación en el Sitio Web de la Comisión de los informes mensuales de control y revisión elaborados durante la vigencia del fideicomiso?",o:["Dentro de los 5 días hábiles","Dentro de los 10 días hábiles","Dentro de los veinte (20) días hábiles","Dentro de los 30 días corridos"],a:2,e:"Veinte días hábiles. Ese informe mensual es donde el inversor consulta el devenir del fideicomiso.",r:"M6 · P117"},
{id:"M6-59",m:6,q:"A los fines de considerar una Oferta Pública con Autorización Automática por su Bajo Impacto, el monto nominal total de los valores fiduciarios emitidos no deberá:",o:["Superar 500.000 UVA o su equivalente, emitidos durante los 6 meses anteriores por el mismo fiduciario","Superar un millón (1.000.000) de UVA o su equivalente en pesos o moneda extranjera, emitidos durante 12 meses anteriores por el mismo fiduciante sin distinción respecto del activo subyacente","Superar 7.000.000 de UVA o su equivalente, emitidos durante los 24 meses anteriores por el mismo fiduciante","Superar 1.000.000 de UVA por cada serie, sin considerar las emisiones anteriores del fiduciante"],a:1,e:"1.000.000 de UVA por fiduciante en los 12 meses anteriores, sin distinguir el activo subyacente.",r:"M6 · P118"},
{id:"M6-103",m:6,q:"El fiduciario que emita bajo el régimen de Oferta Pública con Autorización Automática por su Bajo Impacto estará obligado a:",o:["Obtener una autorización previa de la CNV para cada serie que emita, con dictamen del agente de control y revisión","Proceder a la carga de los datos estructurados de FF y, para los FF bajo los Lineamientos de Valores Negociables Temáticos, presentar informe de revisión externa que acredite la etiqueta temática","Colocar los valores fiduciarios exclusivamente entre inversores del exterior, fuera de los mercados locales autorizados","Publicar estados contables mensuales del fideicomiso y un informe de calificación de riesgo antes de cada colocación"],a:1,e:"Carga de datos estructurados siempre, y si el FF es temático, además, el informe de revisión externa que acredita la etiqueta.",r:"M6 · P119"},
{id:"M6-104",m:6,q:"Para las emisiones de Oferta Pública con Autorización Automática por su Bajo Impacto, el Contrato del Fideicomiso Financiero:",o:["No debe publicarse: alcanza con la publicación del prospecto en la AIF","Debe ser aprobado previamente por la asamblea de tenedores de los valores","Deberá publicarse en la AIF y contener una leyenda especial referida a la emisión del vehículo en el marco del mencionado régimen","Debe publicarse sólo en el boletín del mercado, sin ninguna leyenda adicional"],a:2,e:"Se publica en la Autopista de la Información Financiera, con una leyenda que advierte que la emisión es bajo el régimen de bajo impacto.",r:"M6 · P120"},
{id:"M6-105",m:6,q:"RG 1030/2024. ¿Cuál de los siguientes FCI requiere suscripción exclusivamente por Inversores Calificados?",o:["Fondo Abierto de Renta Variable en dólares bajo régimen especial","El Fondo de Mercado de Dinero en pesos para el público en general","El Fondo de Renta Fija en pesos para el público en general","El Fondo Abierto PyME de la categoría general"],a:0,e:"La RG 1030/2024 reserva a inversores calificados el fondo abierto de renta variable en dólares bajo régimen especial.",r:"M6 · P121"},
{id:"M6-106",m:6,q:"¿Qué nuevo instrumento incorporó la CNV a partir de 2024 para oferta pública en Argentina?",o:["Los cheques de pago diferido","Las obligaciones negociables PyME","CEDEARs de ETFs de gestión pasiva","Las cauciones bursátiles"],a:2,e:"La novedad de 2024 fueron los CEDEARs de ETFs de gestión pasiva.",r:"M6 · P122"},
{id:"M6-124",m:6,q:"FF con autorización automática de bajo impacto: el monto máximo emitido por fiduciante en los últimos 12 meses para acceder al régimen es:",o:["250.000 UVA","5.000.000 UVA","500.000 UVA","1.000.000 UVA"],a:3,e:"El tope del régimen de bajo impacto es 1.000.000 de UVA emitidos por el fiduciante en los últimos 12 meses (igual que la P118).",r:"M6 · P123"},
{id:"M6-125",m:6,q:"FF con emisiones frecuentes (RG 1074/2025). ¿Cuántos fideicomisos debe haber emitido el fiduciario en total?",o:["5","7","10","12"],a:1,e:"Siete en total (y, según la P106, 3 de ellos en los últimos 12 meses).",r:"M6 · P124"},
{id:"M6-35",m:6,q:"RG 1030/2024. Los FCI abiertos para Inversores Calificados en moneda extranjera deben:",o:["Ser suscriptos únicamente en pesos","Ser suscriptos con fondos depositados en el exterior","Invertir el 100% en títulos públicos","Contar con calificación de riesgo"],a:1,e:"Según la RG 1030/2024, se suscriben con fondos depositados en el exterior.",r:"M6 · P125"}
);
